5	/// <summary>
6	/// ITP101: output ports on one component must be unique, and one topic must not be
7	/// published through two different ports of the same component. Two bare
8	/// <c>Publishes(topic)</c> calls collide on the <c>default</c> port.
9	/// </summary>
10	internal sealed class DuplicatePortRule : ITopologyRule
11	{
12	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
13	    {
14	        foreach (var component in context.Builder.Components)
15	        {
16	            var duplicatePorts = component.PublishCalls
17	                .GroupBy(p => p.Port, StringComparer.Ordinal)
18	                .Where(g => g.Count() > 1);
19	
20	            foreach (var group in duplicatePorts)
21	            {
22	                var hint = group.Key == Component.DefaultPort
23	                    ? " A component with multiple outputs must name every port via Publishes(port, topic)."
24	                    : string.Empty;
25	                yield return new TopologyDiagnostic(
26	                    "ITP101",
27	                    DiagnosticSeverity.Error,
28	                    $"The output port '{group.Key}' is used {group.Count()} times.{hint}",
29	                    component.Name);
30	            }
31	
32	            var duplicateTopics = component.PublishCalls
33	                .GroupBy(p => (p.Topic.PubSubName, p.Topic.TopicName))
34	                .Where(g => g.Select(p => p.Port).Distinct(StringComparer.Ordinal).Count() > 1);
35	
36	            foreach (var group in duplicateTopics)
37	            {
