1	using System.Text;
2	using System.Text.Json;
3	using Intropy.Topology.Model;
4	
5	namespace Intropy.Topology.Generation;
6	
7	/// <summary>The target environment a topology is generated for.</summary>
8	public enum GenerationProfile
9	{
10	    /// <summary>Local development: pub/sub backed by Redis, bindings pointed at declared mocks.</summary>
11	    Dev,
12	
13	    /// <summary>Production: backend-neutral component placeholders (real prod generation is downstream).</summary>
14	    Prod,
15	}
16	
17	/// <summary>A single generated artifact: a relative path and its text content.</summary>
18	/// <param name="RelativePath">Path relative to the output root (forward slashes).</param>
19	/// <param name="Content">The file's text content.</param>
20	public sealed record GeneratedFile(string RelativePath, string Content);
21	
22	/// <summary>The artifacts generated for a system: Dapr component YAML and per-component runtime config.</summary>
23	public sealed class GeneratedArtifacts
24	{
25	    /// <summary>Subdirectory holding Dapr component YAML — the value for a sidecar's resources-path.</summary>
26	    public const string ComponentsDir = "components";
27	
28	    /// <summary>Subdirectory holding per-component runtime config.</summary>
29	    public const string ConfigDir = "config";
30	
31	    internal GeneratedArtifacts(IReadOnlyList<GeneratedFile> files) => Files = files;
32	
33	    /// <summary>All generated files, in deterministic order.</summary>
34	    public IReadOnlyList<GeneratedFile> Files { get; }
35	
36	    /// <summary>Writes every artifact under <paramref name="directory"/>, creating subdirectories.</summary>
37	    /// <param name="directory">The output root.</param>
38	    public void WriteTo(string directory)
39	    {
40	        ArgumentException.ThrowIfNullOrEmpty(directory);
41	        foreach (var file in Files)
42	        {
43	            var path = Path.Combine(directory, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
44	            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
45	            File.WriteAllText(path, file.Content);
46	        }
47	    }
48	}
49	
50	/// <summary>Turns a validated <see cref="SystemTopology"/> into Dapr components and runtime config.</summary>
51	public static class TopologyGenerator
52	{
53	    private static readonly JsonSerializerOptions s_json = new() { WriteIndented = true };
54	
55	    /// <summary>Generates the artifacts for a topology under the given profile.</summary>
56	    /// <param name="topology">The validated topology.</param>
57	    /// <param name="profile">The target profile.</param>
58	    /// <param name="dev">Dev-only declarations (mocks/overrides); ignored for <see cref="GenerationProfile.Prod"/>.</param>
59	    /// <returns>The generated artifacts.</returns>
60	    public static GeneratedArtifacts Generate(SystemTopology topology, GenerationProfile profile, DevManifest? dev = null)
61	    {
62	        ArgumentNullException.ThrowIfNull(topology);
63	        var manifest = dev ?? DevManifest.Empty;
64	        var files = new List<GeneratedFile>();
65	
66	        foreach (var topic in topology.Topics.Select(t => t.PubSubName).Distinct(StringComparer.Ordinal))
67	        {
68	            files.Add(PubSubComponent(topic, profile, topology));
69	        }
70	
71	        foreach (var connector in topology.Connectors)
72	        {
73	            files.Add(BindingComponent(connector, profile, manifest));
74	        }
75	
76	        if (profile == GenerationProfile.Dev)
77	        {
78	            foreach (var api in topology.Apis)
79	            {
80	                if (manifest.ApiMockFor(api.Name) is { } apiMock && api.Providers.Count == 1)
81	                {
82	                    files.Add(HttpEndpointForMockedApi(api.Providers[0], apiMock));
83	                }
84	            }
85	        }
86	
87	        foreach (var component in topology.Components)
88	        {
89	            files.Add(ComponentConfig(topology.SystemName, component));
90	        }
91	
92	        return new GeneratedArtifacts(files);
93	    }
94	
95	    private static GeneratedFile PubSubComponent(string pubSubName, GenerationProfile profile, SystemTopology topology)
96	    {
97	        var scopes = topology.Components
98	            .Where(c => c.Subscribes.Any(s => s.PubSubName == pubSubName) || c.Publishes.Any(p => p.PubSubName == pubSubName))
99	            .Select(c => c.Name)
100	            .OrderBy(n => n, StringComparer.Ordinal);
101	
102	        var (type, metadata) = profile == GenerationProfile.Dev
103	            ? ("pubsub.redis", new[] { ("redisHost", "localhost:6379"), ("redisPassword", "") })
104	            : ("pubsub", Array.Empty<(string, string)>());
105	
106	        var yaml = DaprYaml.Component(pubSubName, type, metadata, scopes);
107	        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{pubSubName}.yaml", yaml);
108	    }
109	
110	    private static GeneratedFile BindingComponent(ConnectorResource connector, GenerationProfile profile, DevManifest manifest)
111	    {
112	        var metadata = new List<(string, string)>();
113	        if (connector.Transport is FileTransport file)
114	        {
115	            // Dev artifacts land in per-run temp dirs and the sidecar's cwd is not guaranteed,
116	            // so anchor the folder at generation time (cwd = the SystemHost directory).
117	            metadata.Add(("rootPath", profile == GenerationProfile.Dev ? Path.GetFullPath(file.RootPath) : file.RootPath));
118	        }
119	
120	        // Dev metadata is keyed by external system; an unresolved connector has none to look up.
121	        if (profile == GenerationProfile.Dev && connector.ExternalSystemName is { } externalSystem)
122	        {
123	            var declared = manifest.ConnectorMetadataFor(externalSystem);
124	            if (declared.Count > 0)
125	            {
126	                // The dev profile declared how to reach the mock — emit it verbatim.
127	                metadata.AddRange(declared);
128	            }
129	            else if (connector.Transport?.DaprType == "bindings.http"
130	                && manifest.HttpApiMockFor(externalSystem) is { } httpMock)
131	            {
132	                metadata.Add(("url", httpMock.MockEndpoint));
133	            }
134	            else if (manifest.MockFor(externalSystem) is { Port: { } port })
135	            {
136	                // Dev placeholder endpoint — precise per-transport metadata is a downstream concern.
137	                metadata.Add(connector.Transport?.DaprType == "bindings.http"
138	                    ? ("url", $"http://localhost:{port}")
139	                    : ("endpoint", $"localhost:{port}"));
140	            }
141	        }
142	
143	        // An unresolved connector has no Dapr binding type yet — emit an empty spec.type with a
144	        // TODO marker rather than failing generation. The transport is resolved at system assembly.
145	        var comment = connector.Transport is null
146	            ? "TODO(intropy): transport unresolved — resolve with 'intropy system create'"
147	            : null;
148	        var yaml = DaprYaml.Component(
149	            connector.DaprComponentName, connector.Transport?.DaprType ?? "", metadata, connector.UsedBy, comment);
150	        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{connector.DaprComponentName}.yaml", yaml);
151	    }
152	
153	    // Named after the provider's app-id: Dapr service invocation resolves the name to this endpoint,
154	    // so consumers reach the mock without knowing the provider isn't running.
155	    private static GeneratedFile HttpEndpointForMockedApi(string providerName, DevApiMock mock)
