private static int Generate(Assembly assembly, string[] args)
{
    var directory = args.Skip(1).FirstOrDefault(a => !a.StartsWith('-')) ?? "./out";
    var profile = ParseProfile(args);

    var discovered = SystemDiscovery.Discover(assembly);
    var dev = DevManifest.From(discovered.Definition);
    var artifacts = TopologyGenerator.Generate(discovered.Topology, profile, dev);
    artifacts.WriteTo(directory);

    Console.WriteLine($"generated {artifacts.Files.Count} files ({profile}) to '{directory}':");
    foreach (var file in artifacts.Files)
    {
        Console.WriteLine($"  {file.RelativePath}");
    }

    return 0;
}

private static GenerationProfile ParseProfile(string[] args)
{
    var index = Array.IndexOf(args, "--profile");
    if (index >= 0 && index + 1 < args.Length &&
        Enum.TryParse<GenerationProfile>(args[index + 1], ignoreCase: true, out var profile))
    {
        return profile;
    }

    return GenerationProfile.Dev;
}

