1	using System.Reflection;
2	using Aspire.Hosting;
3	using Aspire.Hosting.ApplicationModel;
4	using CommunityToolkit.Aspire.Hosting.Dapr;
5	using Intropy.Topology.Generation;
6	using Intropy.Topology.Model;
7	using Microsoft.Extensions.DependencyInjection;
8	
9	namespace Intropy.Topology.Aspire;
10	
11	/// <summary>
12	/// The Aspire run-backend. Discovers a system's validated topology, generates dev Dapr components,
13	/// and translates the model into Aspire resources — one project (or dev-override container) per
14	/// component with a Dapr sidecar on its own staged component overlay, Redis behind pub/sub, mock
15	/// containers for declared external systems, and one Microcks instance serving every
16	/// contract-backed mock — then runs it under DCP, subscribers before their publishers.
17	/// Aspire never sees the topology; it receives ordinary resources.
18	/// </summary>
19	public static class IntropyAspire
20	{
21	    /// <summary>Fixed host port for the dev Redis backend (generated pub/sub YAML points here).</summary>
22	    internal const int RedisPort = 6379;
23	
24	    /// <summary>
25	    /// Discovers the system in <paramref name="assembly"/>, generates dev artifacts to a temp folder,
26	    /// builds the Aspire resource graph, and runs it. Requires Docker and the Dapr CLI to be present.
27	    /// </summary>
28	    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
29	    /// <param name="args">Command-line args passed through to the distributed application builder.</param>
30	    /// <returns>A process exit code.</returns>
31	    public static async Task<int> RunAsync(Assembly assembly, string[] args)
32	    {
33	        ArgumentNullException.ThrowIfNull(assembly);
34	        ArgumentNullException.ThrowIfNull(args);
35	
36	        var discovered = SystemDiscovery.Discover(assembly);
37	        var dev = DevManifest.From(discovered.Definition);
38	
39	        var generatedRoot = Path.Combine(
40	            Path.GetTempPath(), "intropy-aspire", $"{discovered.Topology.SystemName}-{Guid.NewGuid():N}");
41	        TopologyGenerator.Generate(discovered.Topology, GenerationProfile.Dev, dev).WriteTo(generatedRoot);
42	
43	        var builder = DistributedApplication.CreateBuilder(args);
44	        Apply(builder, discovered.Topology, dev, generatedRoot);
45	
46	        var app = builder.Build();
47	        await app.RunAsync().ConfigureAwait(false);
48	        return 0;
49	    }
50	
51	    /// <summary>
52	    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
53	    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
54	    /// </summary>
55	    internal static void Apply(
56	        IDistributedApplicationBuilder builder, SystemTopology topology, DevManifest dev, string generatedRoot)
57	    {
58	        // A connector with no transport has no Dapr binding type to run against — you cannot F5 an
59	        // unresolved binding. Fail fast (no run/deploy-time prompting): the transport is resolved at
60	        // system assembly, not here.
61	        var unresolvedConnectors = topology.Connectors
62	            .Where(c => c.Transport is null)
63	            .Select(c => c.Name)
64	            .ToArray();
65	        if (unresolvedConnectors.Length > 0)
66	        {
67	            throw new InvalidOperationException(
68	                $"These connectors have no transport declared (unresolved): {string.Join(", ", unresolvedConnectors)}. " +
69	                "Resolve them with 'intropy system create' before running.");
70	        }
71	
72	        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
73	        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);
74	
75	        // A plain Redis container rather than AddRedis: the generated pub/sub YAML speaks
76	        // password-less plaintext to localhost:6379, while AddRedis fronts Redis with TLS.
77	        var redis = builder
78	            .AddContainer("redis", "docker.io/library/redis", "8")
79	            .WithEndpoint(port: RedisPort, targetPort: RedisPort);
80	        WithTcpReadiness(builder, redis, RedisPort);
81	
82	        // Everything a sidecar dials during component init. Sidecars must wait for these to be
83	        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
84	        // a still-starting mock kills the sidecar.
85	        var backends = new List<IResourceBuilder<IResource>> { redis };
86	        var backendProbes = new List<TcpReadyHealthCheck> { new("localhost", RedisPort) };
87	
88	        foreach (var mock in dev.Mocks)
89	        {
90	            var container = builder.AddContainer($"mock-{mock.ExternalSystemName}", mock.Image);
91	            if (mock.Args.Count > 0)
92	            {
93	                container.WithArgs([.. mock.Args]);
94	            }
95	
96	            if (mock.Port is { } port)
97	            {
98	                container.WithEndpoint(port: port, targetPort: mock.TargetPort ?? port);
99	                WithTcpReadiness(builder, container, port);
100	                backendProbes.Add(new("localhost", port));
101	            }
102	
103	            backends.Add(container);
104	        }
105	
106	        var mockedProviders = MockedApiProviders(topology, dev);
107	        var microcksArtifacts = dev.HttpApiMocks.Select(m => m.ArtifactPath)
108	            .Concat(dev.ApiMocks.Select(m => m.ArtifactPath))
109	            .ToArray();
110	        if (microcksArtifacts.Length > 0)
111	        {
112	            // One Microcks instance serves every contract-backed mock. The generated YAML points at
113	            // the fixed dev port, so pin the host port ("http" is the resource's primary endpoint).
114	            var microcks = builder.AddMicrocks("microcks")
115	                .WithEndpoint("http", e => e.Port = DevHttpMock.Port)
116	                .WithMainArtifacts(microcksArtifacts);
117	            backends.Add(microcks);
118	            backendProbes.Add(new("localhost", DevHttpMock.Port));
119	        }
120	
121	        // Filled after the component loop; the hook closure only reads it at runtime.
122	        var sidecarWaits = new Dictionary<string, string[]>(StringComparer.Ordinal);
123	
124	        // The Dapr toolkit materializes each sidecar as a separate "<component>-dapr-cli" executable
125	        // that does not carry wait annotations, so WaitFor cannot gate it. Hold its start here until
126	        // every backend port answers and, for publishers, until every subscriber sidecar is running.
127	        builder.Eventing.Subscribe<BeforeResourceStartedEvent>(async (evt, cancellationToken) =>
128	        {
129	            if (!evt.Resource.Name.EndsWith("-dapr-cli", StringComparison.Ordinal))
130	            {
131	                return;
132	            }
133	
134	            foreach (var probe in backendProbes)
135	            {
136	                await probe.WaitUntilReadyAsync(TimeSpan.FromMinutes(3), cancellationToken).ConfigureAwait(false);
137	            }
138	
139	            if (sidecarWaits.TryGetValue(evt.Resource.Name, out var subscriberSidecars))
140	            {
141	                var notifications = evt.Services.GetRequiredService<ResourceNotificationService>();
142	                foreach (var sidecar in subscriberSidecars)
143	                {
144	                    await notifications
145	                        .WaitForResourceAsync(sidecar, KnownResourceStates.Running, cancellationToken)
146	                        .ConfigureAwait(false);
147	                }
148	            }
149	        });
150	
151	        var resources = new Dictionary<string, IResourceBuilder<IResource>>(StringComparer.Ordinal);
152	        var waiters = new Dictionary<string, Action<IResourceBuilder<IResource>>>(StringComparer.Ordinal);
153	        var unresolved = new List<string>();
154	        foreach (var component in topology.Components)
155	        {
156	            if (mockedProviders.Contains(component.Name))
157	            {
158	                continue;
159	            }
160	
161	            // Each integration gets its own staged component set: its local files plus the
162	            // generated system overlay, at a stable inspectable path under obj/.
163	            var stagedPath = ComponentOverlay.Stage(builder.AppHostDirectory, component.Name, componentsPath);
164	
165	            if (dev.ComponentImageOverrides.TryGetValue(component.Name, out var image))
166	            {
167	                var container = builder.AddContainer(component.Name, image);
168	                Wire(container, component, stagedPath, configDir, backends);
169	                resources[component.Name] = container;
170	                waiters[component.Name] = dependency => container.WaitFor(dependency);
171	                continue;
172	            }
173	
174	            var projectPath = ProjectConvention.Resolve(builder.AppHostDirectory, component.Name);
175	            if (!File.Exists(projectPath))
176	            {
177	                unresolved.Add($"{component.Name} (expected {projectPath})");
178	                continue;
179	            }
180	
181	            // The endpoint makes Aspire allocate a port and inject ASPNETCORE_URLS (without it every
182	            // Kestrel binds the 5000 default) and gives the Dapr sidecar its app-port.
183	            var project = builder.AddProject(component.Name, projectPath).WithHttpEndpoint();
184	            Wire(project, component, stagedPath, configDir, backends);
185	            resources[component.Name] = project;
186	            waiters[component.Name] = dependency => project.WaitFor(dependency);
187	        }
188	
189	        if (unresolved.Count > 0)
190	        {
191	            throw new InvalidOperationException(
192	                $"No project found for these components by folder convention: {string.Join(", ", unresolved)}. " +
193	                "Create the project or declare a dev override (DevBuilder.Override).");
194	        }
195	
196	        // Subscribers start first, so a publisher's first message finds a registered
197	        // subscription. Nobody declares this: it is derived from who publishes and who
198	        // subscribes each topic. Publish/subscribe cycles cannot be ordered — skip entirely
199	        // rather than deadlock.
200	        var precedence = SubscriberPrecedence(topology);
201	        if (HasCycle(precedence))
202	        {
203	            Console.Error.WriteLine(
204	                "intropy: the topology's topics form a publish/subscribe cycle; " +
205	                "skipping subscriber-first startup ordering.");
206	            return;
207	        }
208	
209	        foreach (var (publisher, subscribers) in precedence)
210	        {
211	            if (!waiters.TryGetValue(publisher, out var wait))
212	            {
213	                continue;
214	            }
215	
216	            var materialized = subscribers.Where(resources.ContainsKey).ToArray();
217	            foreach (var subscriber in materialized)
218	            {
219	                wait(resources[subscriber]);
220	            }
221	
222	            if (materialized.Length > 0)
223	            {
224	                sidecarWaits[$"{publisher}-dapr-cli"] =
225	                    [.. materialized.Select(s => $"{s}-dapr-cli")];
226	            }
227	        }
228	    }
229	
230	    /// <summary>
231	    /// Which components each publisher must wait for: every subscriber of every topic it
232	    /// publishes. Self-loops (a component consuming its own topic) are not orderable edges.
233	    /// </summary>
234	    private static Dictionary<string, HashSet<string>> SubscriberPrecedence(SystemTopology topology)
235	    {
236	        var precedence = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
237	        foreach (var topic in topology.Topics)
238	        {
239	            foreach (var publisher in topic.Publishers)
240	            {
241	                foreach (var subscriber in topic.Subscribers)
242	                {
243	                    if (string.Equals(publisher, subscriber, StringComparison.Ordinal))
244	                    {
245	                        continue;
246	                    }
247	
248	                    if (!precedence.TryGetValue(publisher, out var subscribers))
249	                    {
250	                        precedence[publisher] = subscribers = new HashSet<string>(StringComparer.Ordinal);
251	                    }
252	
253	                    subscribers.Add(subscriber);
254	                }
255	            }
256	        }
257	
258	        return precedence;
259	    }
260	
261	    private static bool HasCycle(Dictionary<string, HashSet<string>> edges)
262	    {
263	        var state = new Dictionary<string, int>(StringComparer.Ordinal); // 1 = visiting, 2 = done
264	
265	        bool Visit(string node)
266	        {
267	            if (state.TryGetValue(node, out var seen))
268	            {
269	                return seen == 1;
270	            }
271	
272	            state[node] = 1;
273	            if (edges.TryGetValue(node, out var next) && next.Any(Visit))
274	            {
275	                return true;
276	            }
277	
278	            state[node] = 2;
279	            return false;
280	        }
281	
282	        return edges.Keys.Any(Visit);
283	    }
284	
285	    /// <summary>
286	    /// Providers whose APIs are dev-mocked are not started: their consumers reach the contract-backed
287	    /// mock through the generated HTTPEndpoint resource named after the provider's app-id. A provider
288	    /// can only be skipped whole, so every API it provides must be mocked.
